hah, you can just do this with a normal consteval function...

https://godbolt.org/z/YorfMqTzq

```
template <typename T, std::size_t N>
consteval auto extractKeys(
    const std::array<std::pair<std::string_view, T>, N>& arr)
{
    std::array<std::string_view, N> ret;
    for (int ctr = 0; ctr < N; ++ctr)
    {
        ret[ctr] = arr[ctr].first;
    }
    return ret;
}
